    'Terminal' => 'เทอร์มินัล',
    'The app-relative path MCP clients connect to, such as `/mcp`.' => 'พาธที่สัมพันธ์กับแอปซึ่งไคลเอนต์ MCP เชื่อมต่อ เช่น `/mcp`',
    'The app-relative path public MCP clients connect to, such as `/mcp`.' => 'พาธที่สัมพันธ์กับแอปซึ่งไคลเอนต์ MCP สาธารณะเชื่อมต่อ เช่น `/mcp`',
    'The app-relative path to give MCP clients that sign in with OAuth. It always requires an access token, so clients can discover how to sign in.' => 'พาธที่สัมพันธ์กับแอปสำหรับมอบให้ไคลเอนต์ MCP ที่ลงชื่อเข้าใช้ด้วย OAuth พาธนี้ต้องใช้โทเคนการเข้าถึงเสมอ เพื่อให้ไคลเอนต์ค้นพบวิธีลงชื่อเข้าใช้ได้',
    'The asset transformer handle has already been taken.' => 'ตัวจัดการของตัวแปลงแอสเซทนี้ถูกใช้ไปแล้ว',
    'The authenticated server uses this endpoint too. Requests without an access token go to the public server, so MCP clients can’t discover how to sign in at this endpoint.' => 'เซิร์ฟเวอร์แบบยืนยันตัวตนก็ใช้ปลายทางนี้ด้วย คำขอที่ไม่มีโทเคนการเข้าถึงจะถูกส่งไปยังเซิร์ฟเวอร์สาธารณะ ดังนั้นไคลเอนต์ MCP จึงไม่สามารถค้นพบวิธีลงชื่อเข้าใช้ที่ปลายทางนี้ได้',
    'The condition isn’t valid.' => 'เงื่อนไขไม่ถูกต้อง',
    'The draft can’t be added to a scheduled release until it’s ready to publish: {errors}' => 'ไม่สามารถเพิ่มแบบร่างลงในรีลีสที่ตั้งเวลาไว้ได้จนกว่าจะพร้อมเผยแพร่: {errors}',
    'The draft could not be published.' => 'ไม่สามารถเผยแพร่แบบร่างได้',
    'The draft could not be validated for publication.' => 'ไม่สามารถตรวจสอบความถูกต้องของแบบร่างสำหรับการเผยแพร่ได้',
