    'The draft no longer exists.' => 'แบบร่างไม่มีอยู่แล้ว',
    'The file “{filename}” has already been added.' => 'เพิ่มไฟล์ “{filename}” ไปแล้ว',
    'The first time your assistant connects, it opens a browser window where you sign in and approve access.' => 'ครั้งแรกที่ผู้ช่วยของคุณเชื่อมต่อ ระบบจะเปิดหน้าต่างเบราว์เซอร์ให้คุณลงชื่อเข้าใช้และอนุมัติการเข้าถึง',
    'The folder is already in the selected location.' => 'โฟลเดอร์อยู่ในตำแหน่งที่เลือกอยู่แล้ว',
