    'The minimum number of approvals required in total or per reviewer group.' => 'จำนวนการอนุมัติขั้นต่ำที่ต้องการทั้งหมด หรือต่อกลุ่มผู้ตรวจทาน',
    'The navigation everyone gets. User group navigations build on it.' => 'การนำทางที่ทุกคนได้รับ การนำทางของกลุ่มผู้ใช้จะสร้างต่อยอดจากการนำทางนี้',
    'The nested element field is no longer available.' => 'ฟิลด์องค์ประกอบที่ซ้อนกันไม่พร้อมใช้งานแล้ว',
