    'The release has no drafts.' => 'รีลีสไม่มีแบบร่าง',
    'The release is no longer scheduled.' => 'รีลีสไม่ได้ตั้งเวลาไว้อีกต่อไป',
    'The release is not due yet.' => 'ยังไม่ถึงกำหนดของรีลีส',
    'The release is not ready to be scheduled.' => 'รีลีสยังไม่พร้อมให้ตั้งเวลา',
    'The release no longer exists.' => 'รีลีสไม่มีอยู่แล้ว',
