    'The reserved [craft] asset transformer must use the [craft] driver.' => 'ตัวแปลงแอสเซท [craft] ที่สงวนไว้ต้องใช้ไดรเวอร์ [craft]',
    'The review for “{entry}” was reset because its workflow changed.' => 'การตรวจทาน “{entry}” ถูกรีเซ็ตเนื่องจากเวิร์กโฟลว์เปลี่ยนไป',
    'The route is invalid.' => 'เส้นทางไม่ถูกต้อง',
    'The scheduled publication time must be in the future.' => 'เวลาเผยแพร่ที่ตั้งไว้ต้องเป็นเวลาในอนาคต',
    'The selected asset transform driver has invalid settings.' => 'ไดรเวอร์การแปลงแอสเซทที่เลือกมีการตั้งค่าไม่ถูกต้อง',
    'The selected asset transform driver is unavailable.' => 'ไดรเวอร์การแปลงแอสเซทที่เลือกไม่พร้อมใช้งาน',
