    'The workflow could not be updated.' => 'ไม่สามารถอัปเดตเวิร์กโฟลว์ได้',
    'The {type} has been deleted.' => 'ลบ {type} แล้ว',
    'There are no jobs in the queue' => 'ไม่มีงานในคิว',
