    'This URL is an MCP server for AI assistants, not a web page. Add it to your assistant to search and read this site’s public content in plain language.' => 'URL นี้เป็นเซิร์ฟเวอร์ MCP สำหรับผู้ช่วย AI ไม่ใช่หน้าเว็บ เพิ่ม URL นี้ลงในผู้ช่วยของคุณเพื่อค้นหาและอ่านเนื้อหาสาธารณะของเว็บไซต์นี้ด้วยภาษาธรรมดา',
    'This URL is an MCP server for AI assistants, not a web page. Add it to your assistant to work with this site’s content and settings in plain language.' => 'URL นี้เป็นเซิร์ฟเวอร์ MCP สำหรับผู้ช่วย AI ไม่ใช่หน้าเว็บ เพิ่ม URL นี้ลงในผู้ช่วยของคุณเพื่อทำงานกับเนื้อหาและการตั้งค่าของเว็บไซต์นี้ด้วยภาษาธรรมดา',
    'This application will be able to:' => 'แอปพลิเคชันนี้จะสามารถ:',
    'This asset transformer cannot be deleted because it is assigned to a volume.' => 'ไม่สามารถลบตัวแปลงแอสเซทนี้ได้ เนื่องจากกำหนดให้กับไดรฟ์ข้อมูลอยู่',
    'This asset transformer cannot be deleted because it is configured as the default.' => 'ไม่สามารถลบตัวแปลงแอสเซทนี้ได้ เนื่องจากกำหนดค่าเป็นค่าเริ่มต้นอยู่',
    'This asset transformer cannot be deleted because it is registered in code.' => 'This asset transformer cannot be deleted because it is registered in code.',
    'This asset transformer’s driver is unavailable.' => 'ไดรเวอร์ของตัวแปลงแอสเซทนี้ไม่พร้อมใช้งาน',
    'This asset transformer’s driver is unavailable. Select an available driver to save it.' => 'ไดรเวอร์ของตัวแปลงแอสเซทนี้ไม่พร้อมใช้งาน เลือกไดรเวอร์ที่ใช้ได้เพื่อบันทึก',
    'This column type has no settings.' => 'ประเภทคอลัมน์นี้ไม่มีการตั้งค่า',
    'This date is for planning only. Scheduling is a separate action.' => 'วันที่นี้ใช้เพื่อการวางแผนเท่านั้น การตั้งเวลาเป็นการดำเนินการแยกต่างหาก',
    'This date is for planning only. The release will not publish until it is explicitly scheduled.' => 'วันที่นี้ใช้เพื่อการวางแผนเท่านั้น รีลีสจะไม่เผยแพร่จนกว่าจะตั้งเวลาอย่างชัดเจน',
    'This disk has been reserved for temporary asset uploads. Please choose a different one for your volume.' => 'ดิสก์นี้สงวนไว้สำหรับการอัปโหลดแอสเซทชั่วคราว โปรดเลือกดิสก์อื่นสำหรับไดรฟ์ข้อมูลของคุณ',
    'This disk reference is invalid.' => 'การอ้างอิงดิสก์นี้ไม่ถูกต้อง',
    'This draft already belongs to an active release.' => 'แบบร่างนี้อยู่ในรีลีสที่ใช้งานอยู่แล้ว',
    'This draft belongs to the scheduled release “{name}”. Saved changes will be included when the release publishes.' => 'แบบร่างนี้อยู่ในรีลีสที่ตั้งเวลาไว้ “{name}” การเปลี่ยนแปลงที่บันทึกไว้จะรวมอยู่เมื่อรีลีสเผยแพร่',
    'This draft belongs to “{name}”. Saved changes will be included when the release publishes.' => 'แบบร่างนี้อยู่ใน “{name}” การเปลี่ยนแปลงที่บันทึกไว้จะรวมอยู่เมื่อรีลีสเผยแพร่',
