    'The Quick Brown Fox' => 'เป็นมนุษย์สุดประเสริฐเลิศคุณค่า',
    'The Reply-To email address Craft CMS should use when sending email.' => 'ควรใช้ที่อยู่อีเมลตอบกลับที่ Craft CMS ขณะส่งอีเมล',
    'The URI can’t begin with the {setting} config setting.' => 'URI ห้ามเริ่มต้นด้วยการตั้งค่าคอนฟิก {setting}',
    'The `Authorization` header that should be sent with GraphQL API requests to use this token.' => 'หัวข้อ `Authorization` ควรส่งพร้อมกับคำขอ GraphQL API เพื่อใช้โทเคนนี้',
    'The allowed values are [{values}]' => 'ค่าที่อนุญาตคือ [{values}]',
    'The asset you’re trying to download does not exist.' => 'ไม่พบแอสเซทที่คุณพยายามดาวน์โหลด',
    'The asset you’re trying to edit does not exist.' => 'ไม่พบแอสเซทที่คุณพยายามแก้ไข',
    'The auth response must contain a credential ID.' => 'การตอบกลับการยืนยันตัวตนต้องมี ID ข้อมูลประจำตัว',
    'The base URL for the site.' => 'URL ฐานสำหรับเว็บไซต์',
    'The base URL to the files in this filesystem. This can begin with an environment variable or alias.' => 'URL พื้นฐานของไฟล์ในระบบไฟล์นี้ ซึ่งสามารถขึ้นต้นด้วยตัวแปรสภาพแวดล้อมหรือนามแฝงได้',
    'The base URL to the files in this filesystem.' => 'URL ฐานไปยังไฟล์ในระบบไฟล์นี้',
    'The base folder path that should be used as the root of the filesystem. This can begin with an environment variable or alias.' => 'เส้นทางโฟลเดอร์พื้นฐานที่ควรใช้เป็นรากของระบบไฟล์ ซึ่งสามารถขึ้นต้นด้วยตัวแปรสภาพแวดล้อมหรือนามแฝงได้',
    'The base folder path that should be used as the root of the filesystem.' => 'เส้นทางของโฟลเดอร์หลักที่ควรใช้เป็นรากของระบบไฟล์',
    'The developer recommends using <a href="{url}">{name}</a> instead.' => 'ผู้พัฒนาแนะนำให้ใช้ <a href="{url}">{name}</a> แทน',
    'The draft could not be saved.' => 'ไม่สามารถบันทึกแบบร่างได้',
    'The draft has been saved.' => 'บันทึกแบบร่างแล้ว',
    'The email address Craft CMS will use when sending email.' => 'ที่อยู่อีเมล Craft CMS จะถูกใช้ในขณะที่ส่งอีเมล',
    'The field layout is invalid.' => 'เค้าโครงฟิลด์ไม่ถูกต้อง',
    'The file failed to upload to the server properly.' => 'ไม่สามารถอัปโหลดไฟล์ไปยังเซิร์ฟเวอร์ได้อย่างถูกต้อง',
    'The file “{name}” does not appear to be an image.' => 'ไฟล์ “{name}” ไม่ได้เป็นภาพ',
    'The filesystem doesn’t contain any files.' => 'ระบบไฟล์ไม่มีไฟล์ใดๆ',
    'The following <a href="{url}">aliases</a> are defined:' => 'มีการกำหนด<a href="{url}">นามแฝง</a>ต่อไปนี้:',
    'The following content is for preview only.' => 'เนื้อหาต่อไปนี้มีไว้สำหรับดูตัวอย่างเท่านั้น',
    'The following licensing {total, plural, =1{issue} other{issues}} can be resolved with a single purchase on Craft Console:' => '{total, plural, =1{ปัญหา} other{ปัญหา}}ด้านใบอนุญาตต่อไปนี้สามารถแก้ไขได้ด้วยการซื้อเพียงครั้งเดียวบน Craft Console:',
    'The following {items} could not be found or are empty. Should they be deleted from the index?' => '{items} ต่อไปนี้ว่างเปล่าหรือขาดหายไป ต้องการลบออกจากดัชนีหรือไม่',
    'The following {items} could not be found. Should they be deleted from the index?' => 'ไม่พบ {items} ต่อไปนี้ ต้องการลบออกจากดัชนีหรือไม่',
    'The format that {type} titles should take when generated.' => 'รูปแบบที่ควรใช้กับชื่อ {type} เมื่อสร้างขึ้น',
    'The image format that transformed images should use.' => 'รูปแบบภาพที่รูปภาพที่จะถูกแปลงควรใช้',
    'The image format “{format}” is not supported.' => 'ไม่รองรับรูปแบบภาพ “{format}”',
    'The label text to display beside the lightswitch’s disabled state.' => 'ข้อความป้ายที่จะแสดงข้างสถานะปิดใช้งานของสวิตช์ไฟ',
    'The label text to display beside the lightswitch’s enabled state.' => 'ข้อความป้ายที่จะแสดงข้างสถานะเปิดใช้งานของสวิตช์ไฟ',
    'The language content in this site will use.' => 'เนื้อหาภาษาที่เว็บไซต์นี้จะใช้',
    'The language that the control panel should use.' => 'ภาษาที่แผงควบคุมควรใช้',
    'The link types that should be available when inserting links.' => 'ประเภทลิงก์ที่จะใช้ได้เมื่อแทรกลิงก์',
    'The loaded project config has more recent changes than your project config YAML files.' => 'การกำหนดค่าโครงการที่โหลดมีการเปลี่ยนแปลงล่าสุดมากกว่าไฟล์การกำหนดค่าโครงการ YAML ของคุณ',
    'The locale that should be used for date and number formatting.' => 'ตำแหน่งที่ตั้งควรถูกนำไปใช้จัดรูปแบบวันที่และตัวเลข',
    'The location where assets can be selected from.' => 'ตำแหน่งที่ใช้เลือกแอสเซทได้',
    'The maximum length (in bytes) the field can hold.' => 'ความยาวสูงสุด (ในหน่วยไบต์) ที่ฟิลด์สามารถเก็บได้',
    'The maximum number of authors that entries in this section can have.' => 'จำนวนรายการผู้สร้างสูงสุดที่มีได้ในส่วนนี้',
    'The maximum number of characters or bytes the field is allowed to have.' => 'จำนวนอักขระหรือไบต์สูงสุดที่มีได้ในฟิลด์',
    'The maximum number of levels this category group can have.' => 'จำนวนระดับสูงสุดที่กลุ่มหมวดหมู่นี้มีได้',
    'The maximum number of levels this section can have.' => 'จำนวนระดับสูงสุดที่ส่วนนี้มีได้',
    'The maximum number of rows the field is allowed to have.' => 'จำนวนแถวสูงสุดที่ฟิลด์สามารถมีได้',
    'The maximum number of {type} that may be selected.' => 'จำนวน {type} สูงสุดที่เลือกได้',
    'The maximum number of {type} the field is allowed to have.' => 'จำนวน {type} สูงสุดที่มีได้ในฟิลด์',
    'The minimum number of authors that entries in this section can have.' => 'จำนวนผู้สร้างขั้นต่ำที่รายการในส่วนนี้มีได้',
    'The minimum number of rows the field is allowed to have.' => 'จำนวนแถวขั้นต่ำที่ฟิลด์สามารถมีได้',
    'The minimum number of {type} that may be selected.' => 'จำนวน {type} ขั้นต่ำที่ต้องเลือก',
    'The minimum number of {type} the field is allowed to have.' => 'จำนวน {type} ขั้นต่ำที่มีได้ในฟิลด์',
    'The name, handle, and driver of a registered asset transformer can’t be changed.' => 'The name, handle, and driver of a registered asset transformer can’t be changed.',
    'The number of minutes that timepicker options should be incremented by. (Authors can enter a specific time manually.)' => 'จำนวนนาทีที่ตัวเลือกเวลาควรเพิ่มขึ้น (ผู้เขียนสามารถป้อนเวลาที่ต้องการด้วยตนเองได้)',
    'The number of seconds that the Retry-After HTTP header should be set to for maintenance mode responses.' => 'จำนวนวินาทีที่จะตั้งค่าในส่วนหัว HTTP Retry-After สำหรับการตอบกลับในโหมดบำรุงรักษา',
    'The path can contain variables like `{slug}` or `{author.username}`.' => 'เส้นทางสามารถมีตัวแปร เช่น "{slug}" หรือ "{author.username}" ได้',
    'The path to a template file within your `templates/` folder.' => 'เส้นทางไปยังไฟล์เทมเพลตในโฟลเดอร์ \'templates/\' ของคุณ',
    'The plugin was removed successfully.' => 'ลบปลั๊กอินสำเร็จแล้ว',
    'The posted condition config is invalid.' => 'การกำหนดค่าเงื่อนไขที่ส่งมาไม่ถูกต้อง',
    'The primary site cannot be disabled.' => 'ไม่สามารถปิดใช้เว็บไซต์หลักได้',
    'The primary site will be loaded by default on the front end.' => 'เว็บไซต์หลักจะได้รับการโหลดตามค่าเริ่มต้นบนส่วนหน้า',
    'The request could not be understood by the server due to malformed syntax.' => 'เซิร์ฟเวอร์ไม่เข้าใจคำขอได้ เนื่องจากมีรูปแบบไวยากรณ์ไม่ถูกต้อง',
    'The requested URL was not found on this server.' => 'ไม่พบ URL ที่ร้องขอในเซิร์ฟเวอร์นี้',
    'The selected condition class is invalid.' => 'คลาสเงื่อนไขที่เลือกไม่ถูกต้อง',
    'The selected {relatedType} {count, plural, =1{contains} other{contain}} validation errors, preventing this {type} from being saved. Edit the {relatedType} to fix them.' => '{relatedType} ที่เลือก{count, plural, =1{ประกอบด้วย} other{ประกอบด้วย}}ข้อผิดพลาดในการตรวจสอบ ซึ่งป้องกันไม่ให้ {type} ถูกบันทึก แก้ไข {relatedType} เพื่อทำการแก้ไข',
    'The selected {type} could not be found.' => 'ไม่พบ {type} ที่เลือก',
    'The server doesn’t meet Craft’s new requirements:' => 'เซิร์ฟเวอร์ไม่ตรงตามข้อกำหนดใหม่ของ Craft:',
    'The subpath cannot overlap with any other volumes sharing the same filesystem.' => 'เส้นทางย่อยห้ามทับซ้อนกับไดรฟ์ข้อมูลอื่นที่ใช้ระบบไฟล์เดียวกัน',
    'The template Craft CMS will use for HTML emails' => 'เทมเพลตที่ Craft CMS จะใช้สำหรับอีเมล HTML',
    'The template Craft CMS will use for HTML emails. Leave blank to use the default template.' => 'เทมเพลตที่ Craft CMS จะใช้สำหรับอีเมล HTML เว้นว่างไว้เพื่อใช้เทมเพลตเริ่มต้น',
    'The template receives `element` and `static` variables. Its output is sanitized and displayed as non-interactive content; form controls, scripts, and registered assets are not supported.' => 'เทมเพลตจะได้รับตัวแปร `element` และ `static` ผลลัพธ์จะถูกทำความสะอาดและแสดงเป็นเนื้อหาที่โต้ตอบไม่ได้ ไม่รองรับตัวควบคุมฟอร์ม สคริปต์ และแอสเซทที่ลงทะเบียนไว้',
    'The template will be rendered with an `element` variable.' => 'เทมเพลตจะถูกเรนเดอร์ด้วยตัวแปร `element`',
    'The text label for the entry creation button.' => 'ชื่อข้อความสำหรับปุ่มสร้างรายการ',
    'The text label for {type} selection buttons.' => 'ชื่อข้อความสำหรับปุ่มเลือก {type}',
    'The text that will be shown if the field doesn’t have a value.' => 'ข้อความจะถูกแสดงขึ้นมา หากฟิลด์ไม่มีค่าใดๆ',
    'The total number of {type} to display per page within the element index.' => 'จำนวน {type} ทั้งหมดที่แสดงต่อหน้าภายในดัชนีองค์ประกอบ',
    'The update can’t be installed :( {message}' => 'ไม่สามารถติดตั้งอัปเดตได้ :( {message}',
    'The update was reverted successfully.' => 'คืนค่าอัปเดตสำเร็จแล้ว',
    'The uploaded file exceeds the maximum allowed size.' => 'ไฟล์ที่อัปโหลดเกินขนาดสูงสุดที่อนุญาต',
    'The user photo provided is not an image.' => 'รูปภาพที่ผู้ใช้ให้มานั้นไม่ใช่รูปภาพ',
    'The user photo provided is not valid.' => 'รูปภาพผู้ใช้ที่ให้มาไม่ถูกต้อง',
    'The values are matched inclusively.' => 'ค่าจะต้องตรงกันทั้งหมด',
    'The volume where pasted or dropped files should be uploaded.' => 'ไดรฟ์ข้อมูลที่จะใช้อัปโหลดไฟล์ที่วางหรือลากมาวาง',
    'The volumes that should be available when selecting assets.' => 'ไดรฟ์ข้อมูลที่จะใช้ได้เมื่อเลือกแอสเซท',
    'The {attribute} field must be a string or array.' => 'ฟิลด์ {attribute} ต้องเป็นสตริงหรืออาร์เรย์',
    'The {attribute} field must contain a `class` value.' => 'ฟิลด์ {attribute} ต้องมีค่า `class`',
    'The {field} field’s {setting} setting has an invalid subpath (“{subpath}”).' => 'การตั้งค่า {setting} ของฟิลด์ {field} มีเส้นทางย่อยที่ไม่ถูกต้อง (“{subpath}”)',
    'The {field} field’s {setting} setting is set to an invalid volume.' => 'การตั้งค่า {setting} ของฟิลด์ {field} ได้รับการตั้งค่าเป็นไดรฟ์ข้อมูลที่ไม่ถูกต้อง',
    'The {name} license is attached to a different Craft CMS license. You can <a class="go" href="{detachUrl}">detach it in Craft Console</a> or <a class="go" href="{buyUrl}">buy a new license</a>.' => 'ใบอนุญาต {name} แนบอยู่กับใบอนุญาต Craft CMS อื่น คุณสามารถ<a class="go" href="{detachUrl}">ยกเลิกการแนบใบอนุญาตดังกล่าวได้ใน Craft Console</a> หรือ<a class="go" href="{buyUrl}">ซื้อใบอนุญาตใหม่</a>',
    'The {name} license is invalid.' => 'ใบอนุญาต {name} ไม่ถูกต้อง',
    'The {numEntries, plural, =1{entry} other {entries}} will be updated once the {numUsers, plural, =1{user is} other{users are}} deleted.' => '{numEntries, plural, =1{รายการ} other{รายการ}}จะถูกอัปเดต เมื่อ{numUsers, plural, =1{ผู้ใช้ถูก} other{ผู้ใช้ถูก}}ลบออก',
    'The {numRelations, plural, =1{relation} other {relations}} will be removed once the {numTargets, plural, =1{{targetTypeSingular} is} other{{targetTypePlural} are}} deleted.' => '{numRelations, plural, =1{ความสัมพันธ์} other{ความสัมพันธ์}}จะถูกลบออก เมื่อ {numTargets, plural, =1{{targetTypeSingular} ถูก} other{{targetTypePlural} ถูก}}ลบออก',
    'The {numTargets, plural, =1{{targetTypeSingular} is} other{{targetTypePlural} are}} referenced by fields in {numSources, number} other {numSources, plural, =1{element} other{elements}}.' => '{numTargets, plural, =1{{targetTypeSingular}นี้} other{{targetTypePlural}เหล่านี้}}ถูกอ้างอิงโดยฟิลด์ใน{numSources, plural, =1{องค์ประกอบ} other{องค์ประกอบ}}อื่น {numSources, number} รายการ',
    'The {numTargets, plural, =1{{targetTypeSingular} is} other{{targetTypePlural} are}} related by {numRelations, number} other {numRelations, plural, =1{{sourceTypeSingular}} other{{sourceTypePlural}}}.' => '{numTargets, plural, =1{{targetTypeSingular}} other{{targetTypePlural}}} เกี่ยวข้องกับ {numRelations, number} {numRelations, plural, =1{{sourceTypeSingular}} other{{sourceTypePlural}}} อื่นๆ',
    'The {type} is invalid.' => '{type} ไม่ถูกต้อง',
    'The “From” name Craft CMS will use when sending email.' => 'ชื่อ “ผู้ส่ง” ที่ Craft CMS จะใช้ในขณะที่ส่งอีเมล',
    'Theme' => 'ธีม',
    'There are no available plugins.' => 'ไม่มีปลั๊กอินที่พร้อมใช้งาน',
    'There was a problem activating the user: {error}' => 'เกิดปัญหาในการเปิดใช้งานผู้ใช้: {error}',
    'There was a problem deactivating the user.' => 'เกิดปัญหาในการปิดใช้งานผู้ใช้',
    'There was a problem impersonating this user.' => 'มีปัญหาในการปลอมตัวเป็นผู้ใช้นี้',
    'There was a problem indexing assets.' => 'เกิดปัญหาในการจัดทำดัชนีแอสเซท',
    'There was a problem sending the password reset email.' => 'มีปัญหาในการส่งอีเมลรีเซ็ตรหัสผ่าน',
    'There was a problem with uploading the file.' => 'มีปัญหาในการอัปโหลดไฟล์',
    'There was a problem with writing the file to the disk.' => 'มีปัญหาในการเขียนไฟล์ลงดิสก์',
    'There was an error relocating the file.' => 'เกิดข้อผิดพลาดในการย้ายตำแหน่งไฟล์',
    'There was an error uploading your photo' => 'เกิดข้อผิดพลาดในการอัปโหลดรูปภาพของคุณ',
    'There was an error uploading your photo: {error}' => 'เกิดข้อผิดพลาดในการอัปโหลดรูปภาพของคุณ: {error}',
    'This OAuth provider cannot be connected to an account.' => 'ไม่สามารถเชื่อมต่อผู้ให้บริการ OAuth นี้กับบัญชีได้',
    'This OAuth provider cannot create new users.' => 'ผู้ให้บริการ OAuth นี้ไม่สามารถสร้างผู้ใช้ใหม่ได้',
    'This action may only be performed with an elevated session.' => 'การดำเนินการนี้สามารถดำเนินการได้เฉพาะกับเซสชันที่ยกระดับขึ้นเท่านั้น',
    'This browser doesn’t support passkeys.' => 'เบราว์เซอร์นี้ไม่รองรับพาสคีย์',
    'This can be left blank if you just want an unlabeled separator.' => 'นี่สามารถเว้นว่างไว้ได้ หากคุณต้องการตัวคั่นแบบไม่มีป้ายกำกับ',
    'This can be set to an environment variable matching one of the option values.' => 'นี่สามารถตั้งค่าเป็นตัวแปรสภาพแวดล้อมที่ตรงกับหนึ่งในค่าของตัวเลือกได้',
    'This can be set to an environment variable with a boolean value ({examples}).' => 'นี่สามารถตั้งค่าเป็นตัวแปรสภาพแวดล้อมด้วยค่าบูลีนได้ ({examples})',
    'This can be set to an environment variable with a valid language ID ({examples}).' => 'นี่สามารถตั้งค่าเป็นตัวแปรสภาพแวดล้อมได้โดยใช้รหัสภาษาที่ถูกต้อง ({examples})',
    'This can be set to an environment variable with a value of a [supported time zone]({url}).' => 'นี่สามารถตั้งค่าเป็นตัวแปรสภาพแวดล้อมได้โดยใช้ค่าของ [เขตเวลาที่รองรับ]({url})',
    'This can be set to an environment variable, or a Twig template that outputs an ID.' => 'นี่สามารถตั้งค่าเป็นตัวแปรสภาพแวดล้อม หรือเทมเพลต Twig ที่ส่งออก ID ได้',
    'This can be set to an environment variable, or a Twig template that outputs comma-separated IDs.' => 'นี่สามารถตั้งค่าเป็นตัวแปรสภาพแวดล้อม หรือเทมเพลต Twig ที่ส่งออก ID ที่คั่นด้วยจุลภาค',
    'This can begin with an environment variable or alias.' => 'นี่สามารถเริ่มต้นด้วยตัวแปรสภาพแวดล้อมหรือนามแฝงได้',
