    'What type of section is this?' => 'นี่คือส่วนประเภทใด',
    'What’s New' => 'มีอะไรใหม่',
    'When enabled, site requests will return a service unavailable response and queued jobs will pause.' => 'เมื่อเปิดใช้งาน คำขอไปยังเว็บไซต์จะได้รับการตอบกลับว่าบริการไม่พร้อมใช้งาน และงานในคิวจะหยุดชั่วคราว',
    'When someone replaces a file, the record of who uploaded the file will be updated as well.' => 'เมื่อมีใครบางคนมาแทนที่ไฟล์ บันทึกของผู้ที่อัปโหลดไฟล์จะได้รับการอัปเดตด้วยเช่นกัน',
    'Where assets should be stored (relative to **Asset Location**) when they are uploaded directly to the field.' => 'ตำแหน่งที่ควรจัดเก็บแอสเซท (เกี่ยวข้องกับ **ตำแหน่งของแอสเซท**) เมื่อมีการอัปโหลดไปยังฟิลด์โดยตรง',
    'Where assets should be stored on the filesystem.' => 'ตำแหน่งที่ควรจัดเก็บแอสเซทไว้ในระบบไฟล์',
    'Where assets should be stored when they are uploaded directly to the field.' => 'ตำแหน่งที่ควรจัดเก็บแอสเซท เมื่อมีการอัปโหลดไปยังฟิลด์โดยตรง',
    'Where do you want to store user photos? Note that the subfolder path can contain variables like {username}.' => 'คุณต้องการเก็บรูปภาพผู้ใช้ไว้ที่ใด โปรดทราบว่าเส้นทางโฟลเดอร์ย่อยสามารถมีตัวแปร เช่น {username} ได้',
    'Where new {type} should be placed by default in the field.' => '{type} ใหม่ควรถูกวางไว้ที่ใดในฟิลด์ตามค่าเริ่มต้น',
    'Where new {type} should be placed by default in the structure.' => '{type} ใหม่ควรถูกวางไว้ที่ใดในโครงสร้างตามค่าเริ่มต้น',
    'Where transforms should be stored on the filesystem.' => 'ควรจัดเก็บการแปลงไว้ที่ใดในระบบไฟล์',
    'Whether HTML should be encoded before rendering the Markdown.' => 'ว่าจะเข้ารหัส HTML ก่อนแสดงผล Markdown หรือไม่',
    'Whether authors should be able to choose which time zone the time is in.' => 'ผู้เขียนควรจะสามารถเลือกเขตเวลาที่จะอยู่ได้หรือไม่',
    'Whether authors should be able to upload files directly to the field, rather than requiring them to select/upload assets via the selection modal.' => 'กำหนดว่าผู้สร้างจะสามารถอัปโหลดไฟล์ไปยังฟิลด์โดยตรง แทนที่พวกเขาจะต้องเลือก/อัปโหลดแอสเซทผ่านโมดอลการเลือกได้หรือไม่',
    'Whether buttons should only show their icons, hiding their text labels.' => 'กำหนดว่าปุ่มจะแสดงเฉพาะไอคอน และซ่อนป้ายข้อความหรือไม่',
    'Whether card views which include this field should show the custom ON/OFF labels, rather than the field name.' => 'กำหนดว่ามุมมองแบบการ์ดที่มีฟิลด์นี้ควรแสดงป้ายเปิด/ปิดแบบกำหนดเอง แทนที่จะแสดงชื่อฟิลด์หรือไม่',
    'Whether custom fields should be validated during public registration.' => 'กำหนดว่าฟิลด์แบบกำหนดเองควรจะได้รับการตรวจสอบยืนยันในระหว่างการลงทะเบียนสาธารณะหรือไม่',
    'Whether the editor should show character, word, and line counts.' => 'ว่าตัวแก้ไขควรแสดงจำนวนอักขระ คำ และบรรทัดหรือไม่',
    'Whether the editor toolbar should be visible.' => 'ว่าควรแสดงแถบเครื่องมือของตัวแก้ไขหรือไม่',
    'Whether the element index should allow viewing nested {type} in a table.' => 'ดัชนีองค์ประกอบควรอนุญาตให้ดู {type} ที่ซ้อนกันในตารางหรือไม่',
    'Whether the field should only render inline Markdown, without wrapping paragraphs.' => 'ว่าฟิลด์ควรแสดงผลเฉพาะ Markdown แบบอินไลน์โดยไม่ครอบด้วยย่อหน้าหรือไม่',
    'Whether the number of elements in this source should be shown beside it in the navigation.' => 'ว่าจะแสดงจำนวนองค์ประกอบในแหล่งที่มานี้ไว้ข้าง ๆ ในการนำทางหรือไม่',
    'Whether the site menu should be shown for {type} selection modals.' => 'กำหนดว่าควรแสดงเมนูเว็บไซต์สำหรับโมดอลการเลือก {type} หรือไม่',
    'Whether the structure of the related {type} should be maintained.' => 'กำหนดว่าโครงสร้างของ {type} ที่เกี่ยวข้องควรได้รับการเก็บรักษาหรือไม่',
    'Whether the table rows should be restricted to those defined by the “Default Values” setting.' => 'กำหนดว่าควรจำกัดแถวของตารางไปยังรายการที่มีการตั้งค่าเป็น "ค่าเริ่มต้น" หรือไม่',
    'Whether this can be dismissed by a user and not shown again.' => 'กำหนดว่าผู้ใช้สามารถปิดรายการนี้ และไม่แสดงอีกได้หรือไม่',
    'Whether to show entries that the user doesn’t have permission to view, per the “View other users’ entries” permission.' => 'กำหนดว่าจะแสดงรายการที่ผู้ใช้ไม่มีสิทธิ์ดู ตามสิทธิ์ "ดูรายการของผู้ใช้คนอื่น" หรือไม่',
    'Whether to show files that the user doesn’t have permission to view, per the “View files uploaded by other users” permission.' => 'กำหนดว่าจะแสดงไฟล์ที่ผู้ใช้ไม่มีสิทธิ์ดูตามสิทธิ์ "ดูไฟล์ที่อัปโหลดโดยผู้ใช้คนอื่น" หรือไม่',
    'Whether to show sections that the user doesn’t have permission to view.' => 'กำหนดว่าควรแสดงส่วนที่ผู้ใช้ไม่มีสิทธิ์ดูหรือไม่',
    'Whether to show volumes that the user doesn’t have permission to view.' => 'กำหนดว่าควรแสดงไดรฟ์ข้อมูลที่ผู้ใช้ไม่มีสิทธิ์ดูหรือไม่',
    'Whether validation errors on the related {type} should prevent the source element from being saved.' => 'ว่าข้อผิดพลาดในการตรวจสอบยืนยันใน {type} ที่เกี่ยวข้องควรป้องกันไม่ให้มีการบันทึกองค์ประกอบแหล่งที่มาหรือไม่',
    'Whether {type} elements should be allowed to relate to themselves.' => 'องค์ประกอบ {type} ควรได้รับอนุญาตให้มีความเกี่ยวข้องกับตัวเองหรือไม่',
    'Which group should this site belong to?' => 'เว็บไซต์นี้ควรอยู่ในกลุ่มไหน',
    'Which icon sets should be selectable?' => 'ควรให้เลือกชุดไอคอนใดได้บ้าง',
    'Which section do you want to pull recent entries from?' => 'คุณต้องการดึงรายการล่าสุดจากส่วนไหน',
    'Which section do you want to save entries to?' => 'คุณต้องการบันทึกรายการไปยังส่วนไหน',
    'Which site should {type} be related from?' => '{type} ควรเกี่ยวข้องกับเว็บไซต์ไหน',
    'Which sites should assets in this volume be saved to?' => 'ควรบันทึกแอสเซทในไดรฟ์ข้อมูลนี้ไปยังเว็บไซต์ใด',
